export const InstantPreviewCTAInline = (props) => {
  const buttonLabel =
    props.buttonLabel != null ? props.buttonLabel : "Start Building";
  const placeholder = props.placeholder;
  const articleType = props.articleType != null ? props.articleType : "auto";

  const [value, setValue] = useState("");
  const [isFocused, setIsFocused] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [detectedArticleType, setDetectedArticleType] = useState("");

  useEffect(() => {
    if (articleType !== "auto") {
      setDetectedArticleType(articleType);
      return;
    }

    if (typeof window !== "undefined") {
      const path = window.location.pathname;
      if (/replit/i.test(path)) {
        setDetectedArticleType("replit");
      } else if (/lovable/i.test(path)) {
        setDetectedArticleType("lovable");
      } else if (/base44|base-44/i.test(path)) {
        setDetectedArticleType("base44");
      } else if (/salesforce|experience-cloud|experience_cloud/i.test(path)) {
        setDetectedArticleType("salesforce");
      } else if (/bolt/i.test(path)) {
        setDetectedArticleType("bolt");
      }
    }
  }, [articleType]);

  const brand = brandThemeByType[detectedArticleType];
  const brandColor = brand ? brand.color : "rgb(247, 196, 6)";
  const brandGradient = brand && brand.gradient ? brand.gradient : null;
  const buttonColor = "#3F3EDF";
  const buttonHover = "#3534C4";
  const buttonTextColor = "#FFFFFF";
  const useLogoPlaceholder = !placeholder && brand;
  const resolvedPlaceholder =
    placeholder || (useLogoPlaceholder ? "" : "Enter any URL to try it out");
  const showCustomPlaceholder = useLogoPlaceholder && !isFocused && !value;
  const fontStack =
    '"DM Sans", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
  const logoStyle = {
    flexShrink: 0,
    opacity: 0.9,
    color: "rgba(28, 28, 28, 0.72)",
  };

  let inputFieldStyle = {
    display: "flex",
    alignItems: "center",
    flexGrow: 1,
    minWidth: 0,
    height: "46px",
    padding: "5px",
    borderRadius: "9px",
    backgroundColor: "#FFFFFF",
    boxShadow: brandColor + " 0px 0px 0px 1.5px",
  };

  if (brandGradient) {
    inputFieldStyle = {
      display: "flex",
      alignItems: "center",
      flexGrow: 1,
      minWidth: 0,
      height: "46px",
      padding: "5px",
      borderRadius: "9px",
      border: "1.5px solid transparent",
      background:
        "linear-gradient(#FFFFFF, #FFFFFF) padding-box, " +
        brandGradient +
        " border-box",
    };
  }

  const formStyle = {
    display: "flex",
    alignItems: "center",
    width: "100%",
    gap: "10px",
  };

  let buttonStyle = {
    display: "flex",
    alignItems: "center",
    gap: "8px",
    height: "46px",
    padding: "0 16px",
    backgroundColor: isHovered ? buttonHover : buttonColor,
    color: buttonTextColor,
    fontSize: "14px",
    fontWeight: 700,
    border: "1.5px solid " + buttonColor,
    borderRadius: "9px",
    cursor: "pointer",
    flexShrink: 0,
    fontFamily: fontStack,
    transition:
      "background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease",
    whiteSpace: "nowrap",
  };

  const normalizeUrlInput = (rawValue) => {
    let v = rawValue || "";
    if (!v) {
      return "https://";
    }
    const m = v.match(/https?:\/\//i);
    if (m) {
      v = v.slice(m.index);
    }
    if (!/^https?:\/\//i.test(v)) {
      if (/^https?:\/[^/]/i.test(v)) {
        v = v.replace(/^https?:\//i, "https://");
      } else if (/^https?:/i.test(v)) {
        v = v.replace(/^https?:/i, "https://");
      } else {
        v = "https://" + v;
      }
    }
    v = v
      .replace(/^(https?:\/\/)+/i, "https://")
      .replace(/^(https:\/\/)+/, "$1");
    return v;
  };

  const handleFocus = (e) => {
    setIsFocused(true);
    if (!value) {
      const nextValue = "https://";
      setValue(nextValue);
      requestAnimationFrame(() => {
        try {
          e.target.setSelectionRange(nextValue.length, nextValue.length);
        } catch (err) {}
      });
    }
  };

  const handleBlur = () => {
    setIsFocused(false);
    if (value === "https://") {
      setValue("");
    }
  };

  const handleChange = (e) => {
    setValue(normalizeUrlInput(e.target.value));
  };

  const handleKeyDown = (e) => {
    const input = e.target;
    const start = input.selectionStart != null ? input.selectionStart : 0;
    const end = input.selectionEnd != null ? input.selectionEnd : 0;

    if (
      (e.key === "Backspace" && start <= 8 && end <= 8) ||
      (e.key === "ArrowLeft" && start <= 8 && end <= 8) ||
      e.key === "Home"
    ) {
      if (e.key !== "Home") {
        e.preventDefault();
      }
      requestAnimationFrame(() => {
        try {
          input.setSelectionRange(8, 8);
        } catch (err) {}
      });
    }

    if (e.key === "Delete" && start < 8) {
      e.preventDefault();
      requestAnimationFrame(() => {
        try {
          input.setSelectionRange(8, 8);
        } catch (err) {}
      });
    }
  };

  const handleClick = (e) => {
    const input = e.target;
    const pos = input.selectionStart != null ? input.selectionStart : 0;
    if (pos < 8 && input.value.startsWith("https://")) {
      requestAnimationFrame(() => {
        try {
          input.setSelectionRange(8, 8);
        } catch (err) {}
      });
    }
  };

  let placeholderLogo = null;
  if (showCustomPlaceholder && detectedArticleType === "replit") {
    placeholderLogo = (
      <ReplitLogo
        width={brand.logoWidth}
        height={brand.logoHeight}
        style={logoStyle}
      />
    );
  } else if (showCustomPlaceholder && detectedArticleType === "lovable") {
    placeholderLogo = (
      <LovableLogo
        width={brand.logoWidth}
        height={brand.logoHeight}
        style={logoStyle}
      />
    );
  } else if (showCustomPlaceholder && detectedArticleType === "base44") {
    placeholderLogo = (
      <Base44Logo
        width={brand.logoWidth}
        height={brand.logoHeight}
        style={logoStyle}
      />
    );
  } else if (showCustomPlaceholder && detectedArticleType === "salesforce") {
    placeholderLogo = (
      <SalesforceLogo
        width={brand.logoWidth}
        height={brand.logoHeight}
        style={logoStyle}
      />
    );
  } else if (showCustomPlaceholder && detectedArticleType === "bolt") {
    placeholderLogo = (
      <BoltLogo
        width={brand.logoWidth}
        height={brand.logoHeight}
        style={logoStyle}
      />
    );
  }

  const placeholderBrandText =
    showCustomPlaceholder && detectedArticleType === "salesforce"
      ? "Experience Cloud"
      : null;

  return (
    <div
      style={{
        display: "block",
        width: "100%",
        margin: "24px 0",
        padding: "8px",
        backgroundColor: "#F4F4F5",
        color: "#1C1C1C",
        fontFamily: fontStack,
        borderRadius: "12px",
        border: "1px solid #E4E4E7",
      }}
    >
      <form
        action="https://median.co/app"
        method="get"
        target="_blank"
        style={formStyle}
      >
        <div style={inputFieldStyle}>
          <div
            style={{
              position: "relative",
              flexGrow: 1,
              minWidth: 0,
              height: "36px",
            }}
          >
            {placeholderLogo ? (
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  right: 0,
                  bottom: 0,
                  left: 0,
                  display: "flex",
                  alignItems: "center",
                  gap: "6px",
                  padding: "6px 8px",
                  pointerEvents: "none",
                  color: "rgba(28, 28, 28, 0.42)",
                  fontSize: "14px",
                  fontWeight: 500,
                  fontFamily: fontStack,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                }}
              >
                <span>Enter your</span>
                {placeholderLogo}
                {placeholderBrandText ? (
                  <span>{placeholderBrandText}</span>
                ) : null}
                <span>URL to try it out</span>
              </div>
            ) : null}
            <input
              type="text"
              name="url"
              value={value}
              onFocus={handleFocus}
              onBlur={handleBlur}
              onChange={handleChange}
              onKeyDown={handleKeyDown}
              onClick={handleClick}
              placeholder={!isFocused ? resolvedPlaceholder : ""}
              required={true}
              style={{
                width: "100%",
                height: "36px",
                padding: "6px 8px",
                background: "transparent",
                color: "#1C1C1C",
                fontSize: "14px",
                fontWeight: 500,
                border: "none",
                outline: "none",
                fontFamily: fontStack,
                position: "relative",
                zIndex: 1,
              }}
            />
          </div>
        </div>
        <button
          type="submit"
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
          style={buttonStyle}
        >
          <span>{buttonLabel}</span>
          <span
            style={{
              display: "inline-flex",
              transform: isHovered ? "translateX(3px)" : "translateX(0)",
              transition: "transform 0.2s ease",
            }}
          >
            <CtaArrow />
          </span>
        </button>
      </form>
    </div>
  );
};
